     1 │ // 内存限流器：滑动窗口，按 key（设备/IP）计数
     2 │ package main
     3 │ 
     4 │ import (
     5 │ 	"sync"
     6 │ 	"time"
     7 │ )
     8 │ 
     9 │ type rateLimiter struct {
    10 │ 	mu       sync.Mutex
    11 │ 	buckets  map[string]*bucket
    12 │ 	limit    int           // 窗口内允许的最大次数
    13 │ 	window   time.Duration // 窗口时长
    14 │ }
    15 │ 
    16 │ type bucket struct {
    17 │ 	count     int
    18 │ 	windowEnd time.Time
    19 │ }
    20 │ 
    21 │ func newRateLimiter(limit int, window time.Duration) *rateLimiter {
    22 │ 	rl := &rateLimiter{
    23 │ 		buckets: map[string]*bucket{},
    24 │ 		limit:   limit,
    25 │ 		window:  window,
    26 │ 	}
    27 │ 	go rl.cleanupLoop()
    28 │ 	return rl
    29 │ }
    30 │ 
    31 │ // Allow 判断 key 是否允许通过本次请求
    32 │ func (rl *rateLimiter) Allow(key string) bool {
    33 │ 	rl.mu.Lock()
    34 │ 	defer rl.mu.Unlock()
    35 │ 	now := time.Now()
    36 │ 	b, ok := rl.buckets[key]
    37 │ 	if !ok || now.After(b.windowEnd) {
    38 │ 		rl.buckets[key] = &bucket{count: 1, windowEnd: now.Add(rl.window)}
    39 │ 		return true
    40 │ 	}
    41 │ 	b.count++
    42 │ 	return b.count <= rl.limit
    43 │ }
    44 │ 
    45 │ func (rl *rateLimiter) cleanupLoop() {
    46 │ 	ticker := time.NewTicker(rl.window)
    47 │ 	defer ticker.Stop()
    48 │ 	for range ticker.C {
    49 │ 		rl.mu.Lock()
    50 │ 		now := time.Now()
    51 │ 		for k, v := range rl.buckets {
    52 │ 			if now.After(v.windowEnd) {
    53 │ 				delete(rl.buckets, k)
    54 │ 			}
    55 │ 		}
    56 │ 		rl.mu.Unlock()
    57 │ 	}
    58 │ }
