   103 │ 
   104 │ // Extract 从页面 HTML 提取流地址
   105 │ func (e *Extractor) Extract(urlStr string) (*StreamInfo, error) {
   106 │ 	roomID := extractRoomID(urlStr)
   107 │ 	if roomID == "" {
   108 │ 		return nil, ErrBadURL
   109 │ 	}
   110 │ 
   111 │ 	html, err := e.fetchPage(urlStr)
   112 │ 	if err != nil {
   113 │ 		return nil, err
   114 │ 	}
   115 │ 
   116 │ 	// 规范化 HTML：抖音 SSR JSON 使用转义引号 \" 与 \u0026，先还原成常规形式再匹配
   117 │ 	clean := normalizeHTML(html)
   118 │ 
   119 │ 	flvURLs := extractFLVURLs(clean)
   120 │ 	hlsURLs := extractHLSURLs(clean)
   121 │ 
   122 │ 	if len(flvURLs) == 0 && len(hlsURLs) == 0 {
   123 │ 		// 页面提示直播结束或需要登录
   124 │ 		if strings.Contains(clean, "直播已结束") || strings.Contains(strings.ToLower(clean), "live ended") {
   125 │ 			return nil, ErrLiveEnded
   126 │ 		}
   127 │ 		if liveEnded(clean) {
   128 │ 			return nil, ErrLiveEnded
   129 │ 		}
   130 │ 		return nil, ErrNoStream
   131 │ 	}
   132 │ 
   133 │ 	// 构建画质选项
   134 │ 	var options []QualityOption
   135 │ 	for qk, u := range flvURLs {
   136 │ 		options = append(options, QualityOption{
   137 │ 			Label:      labelOf(qk),
   138 │ 			QualityKey: qk,
   139 │ 			URL:        u,
   140 │ 			Format:     "flv",
   141 │ 		})
   142 │ 	}
   143 │ 	for qk, u := range hlsURLs {
   144 │ 		// 避免重复：FLV 优先
   145 │ 		if _, ok := flvURLs[qk]; ok {
   146 │ 			continue
   147 │ 		}
   148 │ 		options = append(options, QualityOption{
   149 │ 			Label:      labelOf(qk),
   150 │ 			QualityKey: qk,
   151 │ 			URL:        u,
   152 │ 			Format:     "m3u8",
   153 │ 		})
   154 │ 	}
   155 │ 
   156 │ 	// 画质降序排序（原画优先），同画质 FLV 优先 —— 保证前端默认选中最佳画质
   157 │ 	// 注意：flvURLs/hlsURLs 是 map，遍历顺序随机，必须显式排序
   158 │ 	sort.Slice(options, func(i, j int) bool {
   159 │ 		ri, rj := qualityRank[options[i].QualityKey], qualityRank[options[j].QualityKey]
   160 │ 		if ri != rj {
   161 │ 			return ri > rj
   162 │ 		}
   163 │ 		if options[i].Format != options[j].Format {
   164 │ 			return options[i].Format == "flv"
   165 │ 		}
   166 │ 		return options[i].QualityKey < options[j].QualityKey
   167 │ 	})
   168 │ 
   169 │ 	bestURL, bestFormat := selectBestURL(flvURLs, hlsURLs)
   170 │ 	meta := extractMetadata(clean)
   171 │ 
   172 │ 	return &StreamInfo{
   173 │ 		StreamURL:      bestURL,
   174 │ 		StreamFormat:   bestFormat,
   175 │ 		RoomID:         roomID,
   176 │ 		AnchorName:     meta["anchor_name"],
   177 │ 		Title:          meta["title"],
   178 │ 		IsLive:         meta["is_live"] == "1" || len(flvURLs)+len(hlsURLs) > 0,
   179 │ 		QualityOptions: options,
   180 │ 	}, nil
   181 │ }
   182 │ 
   183 │ // normalizeHTML 规范化抖音 SSR HTML：还原转义引号与 \u0026，便于正则匹配
   184 │ func normalizeHTML(html string) string {
   185 │ 	s := strings.ReplaceAll(html, `\"`, `"`)
   186 │ 	s = strings.ReplaceAll(s, `\u0026`, "&")
   187 │ 	return s
