   351 │ // extractMetadata 从页面 HTML 提取主播名/标题/直播状态
   352 │ func extractMetadata(html string) map[string]string {
   353 │ 	meta := map[string]string{"anchor_name": "", "title": "", "is_live": ""}
   354 │ 
   355 │ 	// 1. <title> 标签
   356 │ 	titleRe := regexp.MustCompile(`<title>(.*?)</title>`)
   357 │ 	if m := titleRe.FindStringSubmatch(html); m != nil {
   358 │ 		pageTitle := m[1]
   359 │ 		if strings.Contains(pageTitle, "抖音直播") {
   360 │ 			main := strings.Trim(strings.Replace(pageTitle, "抖音直播", "", -1), " -–—")
   361 │ 			if strings.Contains(main, "的直播") {
   362 │ 				meta["anchor_name"] = strings.Trim(strings.Replace(main, "的直播", "", -1), " ")
   363 │ 			} else {
   364 │ 				meta["title"] = main
   365 │ 			}
   366 │ 		}
   367 │ 	}
   368 │ 
   369 │ 	// 2. 内嵌 JSON 的 nickname（跳过 undefined 等无效值，取第一个有效主播名）
   370 │ 	nickRe := regexp.MustCompile(`"nickname"\s*:\s*"([^"]*)"`)
   371 │ 	for _, m := range nickRe.FindAllStringSubmatch(html, -1) {
   372 │ 		name := strings.TrimSpace(m[1])
   373 │ 		if name == "" || name == "undefined" || name == "$undefined" {
   374 │ 			continue
   375 │ 		}
   376 │ 		meta["anchor_name"] = name
   377 │ 		break
   378 │ 	}
   379 │ 
   380 │ 	// 3. 内嵌 JSON 的 title（同样跳过无效值）
   381 │ 	rtRe := regexp.MustCompile(`"title"\s*:\s*"([^"]*)"`)
   382 │ 	for _, m := range rtRe.FindAllStringSubmatch(html, -1) {
   383 │ 		t := strings.TrimSpace(m[1])
   384 │ 		if t == "" || t == "undefined" || t == "$undefined" || t == meta["anchor_name"] {
   385 │ 			continue
   386 │ 		}
   387 │ 		if meta["title"] == "" {
   388 │ 			meta["title"] = t
   389 │ 			break
   390 │ 		}
   391 │ 	}
   392 │ 
   393 │ 	// 4. 直播状态：页面存在流地址即认为在直播
   394 │ 	hasStreamRe := regexp.MustCompile(`https?://pull-[^"\s<>]+\.(?:flv|m3u8)`)
   395 │ 	if hasStreamRe.MatchString(html) {
   396 │ 		meta["is_live"] = "1"
   397 │ 	}
   398 │ 
   399 │ 	// 5. 兜底：出现 nickname 也认为页面正常加载了直播间
   400 │ 	if meta["is_live"] == "" && strings.Contains(html, `"nickname"`) {
   401 │ 		meta["is_live"] = "1"
   402 │ 	}
   403 │ 
   404 │ 	return meta
   405 │ }
