   167 │ // recordFLV 直接 GET FLV 流并写入文件
   168 │ func (r *Recorder) recordFLV(ctx context.Context, client *http.Client, streamURL, outputPath string) {
   169 │ 	req, err := http.NewRequestWithContext(ctx, http.MethodGet, streamURL, nil)
   170 │ 	if err != nil {
   171 │ 		r.finishWithError(err)
   172 │ 		return
   173 │ 	}
   174 │ 	req.Header.Set("User-Agent", r.cfg.UserAgent)
   175 │ 	req.Header.Set("Referer", r.cfg.Referer)
   176 │ 
   177 │ 	resp, err := client.Do(req)
   178 │ 	if err != nil {
   179 │ 		r.finishWithError(err)
   180 │ 		return
   181 │ 	}
   182 │ 	defer resp.Body.Close()
   183 │ 
   184 │ 	if resp.StatusCode != http.StatusOK {
   185 │ 		r.finishWithError(fmt.Errorf("流地址返回 HTTP %d", resp.StatusCode))
   186 │ 		return
   187 │ 	}
   188 │ 
   189 │ 	f, err := os.Create(outputPath)
   190 │ 	if err != nil {
   191 │ 		r.finishWithError(err)
   192 │ 		return
   193 │ 	}
   194 │ 	defer f.Close()
   195 │ 
   196 │ 	// 限时录制
   197 │ 	var timer *time.Timer
   198 │ 	if r.cfg.MaxDuration > 0 {
   199 │ 		timer = time.AfterFunc(r.cfg.MaxDuration, func() { r.cancel() })
   200 │ 		defer timer.Stop()
   201 │ 	}
   202 │ 
   203 │ 	// 流式拷贝并累计字节
   204 │ 	buf := make([]byte, 256*1024)
   205 │ 	for {
   206 │ 		select {
   207 │ 		case <-ctx.Done():
   208 │ 			r.markStopped()
   209 │ 			return
   210 │ 		default:
   211 │ 		}
   212 │ 
   213 │ 		n, rerr := resp.Body.Read(buf)
   214 │ 		if n > 0 {
   215 │ 			if _, werr := f.Write(buf[:n]); werr != nil {
   216 │ 				r.finishWithError(werr)
   217 │ 				return
   218 │ 			}
   219 │ 			r.mu.Lock()
   220 │ 			r.stats.BytesWritten += int64(n)
   221 │ 			r.mu.Unlock()
   222 │ 		}
   223 │ 		if rerr != nil {
   224 │ 			if rerr == io.EOF {
   225 │ 				// 流正常结束或断开，尝试重连（简单策略：直接停止）
   226 │ 				r.markStopped()
   227 │ 			} else {
   228 │ 				r.finishWithError(rerr)
   229 │ 			}
   230 │ 			return
   231 │ 		}
   232 │ 	}
   233 │ }
