   235 │ // recordHLS 简单 M3U8 录制（下载分片合并）。第一版仅支持单层 m3u8 播放列表。
   236 │ func (r *Recorder) recordHLS(ctx context.Context, streamURL, outputPath string) {
   237 │ 	client := &http.Client{Timeout: 15 * time.Second}
   238 │ 
   239 │ 	// 1. 下载 m3u8 索引
   240 │ 	req, err := http.NewRequestWithContext(ctx, http.MethodGet, streamURL, nil)
   241 │ 	if err != nil {
   242 │ 		r.finishWithError(err)
   243 │ 		return
   244 │ 	}
   245 │ 	req.Header.Set("User-Agent", r.cfg.UserAgent)
   246 │ 	req.Header.Set("Referer", r.cfg.Referer)
   247 │ 
   248 │ 	resp, err := client.Do(req)
   249 │ 	if err != nil {
   250 │ 		r.finishWithError(err)
   251 │ 		return
   252 │ 	}
   253 │ 	body, _ := io.ReadAll(resp.Body)
   254 │ 	resp.Body.Close()
   255 │ 	if resp.StatusCode != http.StatusOK {
   256 │ 		r.finishWithError(fmt.Errorf("m3u8 索引返回 HTTP %d", resp.StatusCode))
   257 │ 		return
   258 │ 	}
   259 │ 
   260 │ 	// 2. 提取分片 URL
   261 │ 	segments := parseM3U8Segments(string(body), streamURL)
   262 │ 	if len(segments) == 0 {
   263 │ 		r.finishWithError(errors.New("m3u8 中没有找到分片"))
   264 │ 		return
   265 │ 	}
   266 │ 
   267 │ 	f, err := os.Create(outputPath)
   268 │ 	if err != nil {
   269 │ 		r.finishWithError(err)
   270 │ 		return
   271 │ 	}
   272 │ 	defer f.Close()
   273 │ 
   274 │ 	for _, segURL := range segments {
   275 │ 		select {
   276 │ 		case <-ctx.Done():
   277 │ 			r.markStopped()
   278 │ 			return
   279 │ 		default:
   280 │ 		}
   281 │ 		seg, err := client.Get(segURL)
   282 │ 		if err != nil {
   283 │ 			continue // 单个分片失败跳过
   284 │ 		}
   285 │ 		if seg.StatusCode != http.StatusOK {
   286 │ 			seg.Body.Close()
   287 │ 			continue
   288 │ 		}
   289 │ 		n, _ := io.Copy(f, seg.Body)
   290 │ 		seg.Body.Close()
   291 │ 		r.mu.Lock()
   292 │ 		r.stats.BytesWritten += n
   293 │ 		r.mu.Unlock()
   294 │ 	}
   295 │ 
   296 │ 	r.markStopped()
   297 │ }
