   299 │ // parseM3U8Segments 解析 m3u8 分片 URL（支持相对/绝对路径）
   300 │ func parseM3U8Segments(content, baseURL string) []string {
   301 │ 	var segs []string
   302 │ 	lines := strings.Split(content, "\n")
   303 │ 	base := baseURL
   304 │ 	if idx := strings.LastIndex(baseURL, "/"); idx >= 0 {
   305 │ 		base = baseURL[:idx+1]
   306 │ 	}
   307 │ 	for _, line := range lines {
   308 │ 		line = strings.TrimSpace(line)
   309 │ 		if line == "" || strings.HasPrefix(line, "#") {
   310 │ 			continue
   311 │ 		}
