const maxNonceStore = 100000

func (ns *nonceStore) checkAndSet(nonce string) bool {
	ns.mu.Lock()
	defer ns.mu.Unlock()
	if _, ok := ns.seen[nonce]; ok {
		return false // 已用过 = 重放
	}
	// 容量保护：超过上限时先清理过期项，仍满则拒绝（防内存撑爆）
	if len(ns.seen) >= maxNonceStore {
		cutoff := time.Now().Add(-ns.ttl)
		for k, v := range ns.seen {
			if v.Before(cutoff) {
				delete(ns.seen, k)
			}
		}
	}
	if len(ns.seen) >= maxNonceStore {
		return false
	}
	ns.seen[nonce] = time.Now()
	return true
}
