func verifySignature(r *http.Request, token string) (bool, string) {
	ts := r.Header.Get("X-Timestamp")
	nonce := r.Header.Get("X-Nonce")
	sign := r.Header.Get("X-Sign")
	if ts == "" || nonce == "" || sign == "" {
		return false, "缺少签名头 (X-Timestamp/X-Nonce/X-Sign)"
