// TestDoubleStartStopNoPanic：连续两次 Start→Stop 必须不 panic（回归修复 close of closed channel）
func TestDoubleStartStopNoPanic(t *testing.T) {
	// 本地模拟 FLV 流服务器
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "video/x-flv")
		flusher, _ := w.(http.Flusher)
		chunk := make([]byte, 1024*16)
		for i := 0; i < 30; i++ {
			if _, err := w.Write(chunk); err != nil {
				return
			}
			if flusher != nil {
				flusher.Flush()
			}
			time.Sleep(50 * time.Millisecond)
		}
	}))
	defer srv.Close()

	tmp := t.TempDir()
	dir := filepath.Join(tmp, "recordings")
	_ = os.MkdirAll(dir, 0o755)

	r := New(Config{OutputDir: dir})

	for i := 1; i <= 2; i++ {
		// 每次用不存在的文件名 → 不触发防覆盖逻辑，专门验证 panic 修复
		out, err := r.Start(srv.URL+"/stream.flv", fmt.Sprintf("panic_test_%d", i))
		if err != nil {
			t.Fatalf("第 %d 次 Start 失败: %v", i, err)
		}
		time.Sleep(200 * time.Millisecond) // 让流写入一些数据
		r.Stop()
		// 第二次 Stop 后再确认状态已复位
		if r.IsRecording() {
			t.Fatalf("第 %d 次 Stop 后 IsRecording 仍为 true", i)
		}
		t.Logf("第 %d 次 Start→Stop 正常（输出 %s）", i, out)
	}

	// 第三轮：验证 Stop 可重复调用不 panic
	r.Stop()
	r.Stop()
	t.Log("连续 2 次 Start→Stop + 额外 2 次 Stop 全部正常，无 panic")
}

// TestFileOverwriteSuffix：重名文件自动加后缀不覆盖
func TestFileOverwriteSuffix(t *testing.T) {
	tmp := t.TempDir()
	dir := filepath.Join(tmp, "recordings")
	_ = os.MkdirAll(dir, 0o755)

	// 预置同名文件
