$ErrorActionPreference = 'Continue'
$base = 'http://111.170.152.215:18080'
$adminKey = 'e879d26433cddd359c1751780ad9fb02b0eb0cadec6e4abd7290ab5cb6886652'
$deviceId = 'prodverify' + (Get-Random -Minimum 100000 -Maximum 999999)

function Sign-Hmac($token, $method, $path, $body) {
  $ts = [DateTimeOffset]::UtcNow.ToUnixTimeSeconds().ToString()
  $nonce = ([guid]::NewGuid().ToString('N')).Substring(0,16)
  $sha = [System.Security.Cryptography.SHA256]::Create()
  $bodyHash = [Convert]::ToHexString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($body))).ToLower()
  $msg = "$method`n$path`n$ts`n$nonce`n$bodyHash"
  $hmac = New-Object System.Security.Cryptography.HMACSHA256
  $hmac.Key = [Text.Encoding]::UTF8.GetBytes($token)
  $sign = [Convert]::ToHexString($hmac.ComputeHash([Text.Encoding]::UTF8.GetBytes($msg))).ToLower()
  return @{ ts=$ts; nonce=$nonce; sign=$sign }
}

# 1. gencode（生产 admin key）
Write-Output '=== 1. gencode ==='
try {
  $h = @{ 'X-Admin-Key' = $adminKey; 'Content-Type' = 'application/json' }
  $r = Invoke-RestMethod -Uri "$base/api/admin/gencode" -Method Post -Headers $h -Body '{"days":30,"note":"prod ssrf verify","n":1}' -TimeoutSec 15
  $code = $r.codes[0]
  Write-Output "OK code=$code"
} catch { Write-Output "FAIL: $($_.Exception.Message)"; if ($_.ErrorDetails.Message) { Write-Output $_.ErrorDetails.Message } ; exit 1 }

# 2. register
Write-Output '=== 2. register ==='
try {
  $h = @{ 'Content-Type' = 'application/json' }
  $body = @{ code=$code; device_id=$deviceId } | ConvertTo-Json -Compress
  $r = Invoke-RestMethod -Uri "$base/api/register" -Method Post -Headers $h -Body $body -TimeoutSec 15
  $token = $r.token
  Write-Output "OK device=$deviceId token=$($token.Substring(0,8))..."
} catch { Write-Output "FAIL: $($_.Exception.Message)" ; exit 1 }

# 3. 签名解析 - evil URL（SSRF 防护验证）
Write-Output '=== 3. parse evil.com URL（SSRF 防护）==='
try {
  $p = Sign-Hmac $token 'POST' '/api/parse' '{"url":"https://evil.com/1234567890"}'
  $h = @{ 'X-Token'=$token; 'X-Timestamp'=$p.ts; 'X-Nonce'=$p.nonce; 'X-Sign'=$p.sign; 'Content-Type'='application/json' }
  $resp = Invoke-WebRequest -Uri "$base/api/parse" -Method Post -Headers $h -Body '{"url":"https://evil.com/1234567890"}' -TimeoutSec 15 -SkipHttpErrorCheck
  Write-Output "HTTP $($resp.StatusCode): $($resp.Content)"
  if ($resp.StatusCode -ne 400 -and $resp.Content -notmatch 'URL') { Write-Output "WARN: 期望 URL 格式错误被拒" }
} catch { Write-Output "FAIL: $($_.Exception.Message)" }

# 4. 签名解析 - 合法 URL（鉴权通过验证）
Write-Output '=== 4. parse live.douyin.com（鉴权链路）==='
try {
  $p = Sign-Hmac $token 'POST' '/api/parse' '{"url":"https://live.douyin.com/985706671742"}'
  $h = @{ 'X-Token'=$token; 'X-Timestamp'=$p.ts; 'X-Nonce'=$p.nonce; 'X-Sign'=$p.sign; 'Content-Type'='application/json' }
  $resp = Invoke-WebRequest -Uri "$base/api/parse" -Method Post -Headers $h -Body '{"url":"https://live.douyin.com/985706671742"}' -TimeoutSec 20 -SkipHttpErrorCheck
  Write-Output "HTTP $($resp.StatusCode): $($resp.Content)"
} catch { Write-Output "FAIL: $($_.Exception.Message)" }

# 5. 错误 token（鉴权拒绝验证）
Write-Output '=== 5. parse 错误 token（应 401）==='
try {
  $p = Sign-Hmac 'wrongtoken' 'POST' '/api/parse' '{}'
  $h = @{ 'X-Token'='wrongtoken'; 'X-Timestamp'=$p.ts; 'X-Nonce'=$p.nonce; 'X-Sign'=$p.sign; 'Content-Type'='application/json' }
  $resp = Invoke-WebRequest -Uri "$base/api/parse" -Method Post -Headers $h -Body '{}' -TimeoutSec 15 -SkipHttpErrorCheck
  Write-Output "HTTP $($resp.StatusCode): $($resp.Content)"
} catch { Write-Output "FAIL: $($_.Exception.Message)" }

