    48 │ // ---- 本地持久化配置 ----
    49 │ 
    50 │ const configFile = "v3-client-config.json"
    51 │ 
    52 │ type Config struct {
    53 │ 	ServerURL string `json:"server_url"`
    54 │ 	DeviceID  string `json:"device_id"`
    55 │ 	Token     string `json:"token"`
    56 │ }
    57 │ 
    58 │ // configPath 配置文件放在程序所在目录（解压即用场景）
    59 │ func configPath() string {
    60 │ 	exe, err := os.Executable()
    61 │ 	if err != nil {
    62 │ 		return configFile
    63 │ 	}
    64 │ 	return filepath.Join(filepath.Dir(exe), configFile)
    65 │ }
    66 │ 
    67 │ // LoadConfig 读取本地配置；不存在则返回空 Config（未激活）
