    97 │ // ---- 客户端 ----
    98 │ 
    99 │ type Client struct {
   100 │ 	ServerURL string
   101 │ 	Token     string
   102 │ 	DeviceID  string
   103 │ 	http      *http.Client
   104 │ }
   105 │ 
   106 │ func New(serverURL, deviceID, token string) *Client {
   107 │ 	return &Client{
   108 │ 		ServerURL: stringsTrimSlash(serverURL),
   109 │ 		Token:     token,
   110 │ 		DeviceID:  deviceID,
   111 │ 		http:      &http.Client{Timeout: 45 * time.Second},
   112 │ 	}
   113 │ }
   114 │ 
   115 │ func stringsTrimSlash(s string) string {
   116 │ 	for len(s) > 0 && s[len(s)-1] == '/' {
   117 │ 		s = s[:len(s)-1]
   118 │ 	}
   119 │ 	return s
   120 │ }
   121 │ 
   122 │ // ---- 签名 ----
   123 │ 
   124 │ // sign 计算 HMAC 签名（与服务端 signature.go 一致）
   125 │ func (c *Client) sign(method, path, ts, nonce string, body []byte) string {
   126 │ 	bodyHash := sha256.Sum256(body)
   127 │ 	msg := fmt.Sprintf("%s\n%s\n%s\n%s\n%s", method, path, ts, nonce, hex.EncodeToString(bodyHash[:]))
   128 │ 	mac := hmac.New(sha256.New, []byte(c.Token))
   129 │ 	mac.Write([]byte(msg))
   130 │ 	return hex.EncodeToString(mac.Sum(nil))
   131 │ }
   132 │ 
   133 │ // signedRequest 组装带签名头的请求
   134 │ func (c *Client) signedRequest(method, path string, payload interface{}) (*http.Request, error) {
   135 │ 	var body []byte
   136 │ 	var err error
   137 │ 	if payload != nil {
   138 │ 		body, err = json.Marshal(payload)
   139 │ 		if err != nil {
   140 │ 			return nil, err
   141 │ 		}
   142 │ 	}
   143 │ 	ts := fmt.Sprintf("%d", time.Now().Unix())
   144 │ 	nonceBytes := make([]byte, 16)
   145 │ 	if _, err := rand.Read(nonceBytes); err != nil {
   146 │ 		return nil, err
   147 │ 	}
   148 │ 	nonce := hex.EncodeToString(nonceBytes)
   149 │ 
   150 │ 	req, err := http.NewRequest(method, c.ServerURL+path, bytes.NewReader(body))
   151 │ 	if err != nil {
   152 │ 		return nil, err
   153 │ 	}
   154 │ 	req.Header.Set("Content-Type", "application/json")
   155 │ 	req.Header.Set("X-Token", c.Token)
   156 │ 	req.Header.Set("X-Timestamp", ts)
   157 │ 	req.Header.Set("X-Nonce", nonce)
   158 │ 	req.Header.Set("X-Sign", c.sign(method, path, ts, nonce, body))
   159 │ 	return req, nil
   160 │ }
   161 │ 
   162 │ // do 执行请求并解析 JSON 响应
   163 │ func (c *Client) do(req *http.Request, out interface{}) error {
   164 │ 	resp, err := c.http.Do(req)
   165 │ 	if err != nil {
   166 │ 		return fmt.Errorf("无法连接服务器: %v", err)
   167 │ 	}
   168 │ 	defer resp.Body.Close()
   169 │ 
   170 │ 	data, _ := io.ReadAll(resp.Body)
   171 │ 	if resp.StatusCode != http.StatusOK {
   172 │ 		var e struct {
   173 │ 			Error string `json:"error"`
   174 │ 		}
   175 │ 		_ = json.Unmarshal(data, &e)
   176 │ 		msg := e.Error
   177 │ 		if msg == "" {
   178 │ 			msg = string(data)
   179 │ 		}
   180 │ 		switch resp.StatusCode {
   181 │ 		case http.StatusForbidden:
   182 │ 			return errors.New(msg) // 激活码失效/设备数上限
   183 │ 		case http.StatusUnauthorized:
   184 │ 			return errors.New("授权校验失败: " + msg)
   185 │ 		case http.StatusTooManyRequests:
   186 │ 			return errors.New(msg)
   187 │ 		case http.StatusBadGateway:
   188 │ 			return errors.New(msg)
   189 │ 		default:
   190 │ 			return fmt.Errorf("服务器返回 %d: %s", resp.StatusCode, msg)
   191 │ 		}
   192 │ 	}
   193 │ 	if out != nil {
   194 │ 		return json.Unmarshal(data, out)
   195 │ 	}
   196 │ 	return nil
   197 │ }
