package apiclient

import (
	"bytes"
	"encoding/json"
	"fmt"
	"math/rand"
	"net/http"
	"strings"
	"testing"
)

// TestProdVerifyFullChain 生产全链路验证：
// gencode → register → SSRF 防护（evil URL 被拒）→ 合法 URL 鉴权通过 → 错误 token 401
func TestProdVerifyFullChain(t *testing.T) {
	base := "http://111.170.152.215:18080"
	admin := "e879d26433cddd359c1751780ad9fb02b0eb0cadec6e4abd7290ab5cb6886652"

	// 1. gencode（生产 admin key）
	req, _ := http.NewRequest(http.MethodPost, base+"/api/admin/gencode",
		bytes.NewReader([]byte(`{"days":30,"note":"prod verify","n":1}`)))
	req.Header.Set("X-Admin-Key", admin)
	req.Header.Set("Content-Type", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		t.Fatalf("gencode: %v", err)
	}
	var gr struct {
		Codes []string `json:"codes"`
	}
	_ = json.NewDecoder(resp.Body).Decode(&gr)
	resp.Body.Close()
	if resp.StatusCode != 200 || len(gr.Codes) == 0 {
		t.Fatalf("gencode: status=%d codes=%v", resp.StatusCode, gr.Codes)
	}
	code := gr.Codes[0]
	t.Logf("1. gencode OK: %s", code)

	// 2. register（device_id 满足字符集约束）
	device := fmt.Sprintf("prodverify%06d", rand.Intn(999999))
	c := New(base, device, "")
	reg, err := c.Register(code)
	if err != nil {
		t.Fatalf("register: %v", err)
	}
	t.Logf("2. register OK: device=%s token=%s...", reg.DeviceID, reg.Token[:8])

	// 3. SSRF 防护：evil URL 必须被拒
	evil := New(base, device, reg.Token)
	_, err = evil.Parse("https://evil.com/1234567890")
	if err == nil {
		t.Fatalf("SSRF 防护失效: evil URL 未被拒绝")
	}
	t.Logf("3. SSRF OK: evil URL 被拒 → %v", err)

	// 4. 合法 URL：鉴权必须通过（业务返回未开播属正常）
	ok := New(base, device, reg.Token)
	_, err = ok.Parse("https://live.douyin.com/985706671742")
	if err != nil {
		if strings.Contains(err.Error(), "授权校验失败") {
			t.Fatalf("合法 URL 鉴权未通过: %v", err)
		}
		t.Logf("4. 鉴权通过（业务响应）: %v", err)
	} else {
		t.Logf("4. 鉴权通过 + 解析成功")
	}

	// 5. 错误 token：必须 401 拒绝
	bad := New(base, device, "wrongtoken")
	_, err = bad.Parse("https://live.douyin.com/985706671742")
	if err == nil || !strings.Contains(err.Error(), "授权校验失败") {
		t.Fatalf("错误 token 未被拒: %v", err)
	}
	t.Logf("5. 错误 token 401 OK: %v", err)
}

