if (Test-Path "$env:USERPROFILE\.gitconfig") { Get-Content "$env:USERPROFILE\.gitconfig" -Raw | ForEach-Object { $_ -replace '(?<=token\s*=\s*)\S+','***' } } else { Write-Output 'no .gitconfig' }

# 检查并终止卡住的 winget / 相关安装进程
Write-Output '=== 残留安装进程检查 ==='
$targets = @('winget','GitHub.cli','WindowsPackageManagerServer','msiexec')
foreach ($n in $targets) {
  $p = Get-Process -Name $n -ErrorAction SilentlyContinue
  if ($p) { foreach ($proc in $p) { Write-Output "终止: $($proc.ProcessName) PID=$($proc.Id)"; Stop-Process -Id $proc.Id -Force -ErrorAction SilentlyContinue } }
}
Start-Sleep -Seconds 2
Write-Output '=== 终止后复查 ==='
Get-Process -Name 'winget','WindowsPackageManagerServer','msiexec' -ErrorAction SilentlyContinue | Select-Object ProcessName, Id
if (-not (Get-Process -Name 'winget','WindowsPackageManagerServer','msiexec' -ErrorAction SilentlyContinue)) { Write-Output '安装进程已全部终止' }
Write-Output '=== git/gh 是否部分装上 ==='
foreach ($e in @('C:\Program Files\Git\cmd\git.exe','C:\Program Files\GitHub CLI\gh.exe')) { if (Test-Path $e) { Write-Output "已存在: $e" } else { Write-Output "未安装: $e" } }

# 1. 探测最新 MinGit 版本（GitHub API）
Write-Output '=== 查询最新版本 ==='
try {
  $rel = Invoke-RestMethod -Uri 'https://api.github.com/repos/git-for-windows/git/releases/latest' -TimeoutSec 15 -Headers @{'User-Agent'='xuanji'}
  Write-Output "latest: $($rel.tag_name)"
} catch { Write-Output "GitHub API 失败: $($_.Exception.Message)" }
# 2. 测速：GitHub 直连 vs npmmirror 镜像（下载一个 1MB 测试段）
Write-Output '=== 测速 GitHub 直连 ==='
$sw = [System.Diagnostics.Stopwatch]::StartNew()
try {
  $r = Invoke-WebRequest -Uri 'https://github.com/git-for-windows/git/releases/latest' -Method Head -TimeoutSec 10 -MaximumRedirection 3 -ErrorAction Stop
  $sw.Stop(); Write-Output "GitHub 直连: OK $($sw.ElapsedMilliseconds)ms"
} catch { $sw.Stop(); Write-Output "GitHub 直连失败: $($_.Exception.Message) ($($sw.ElapsedMilliseconds)ms)" }
Write-Output '=== 测速 npmmirror 镜像 ==='
$sw = [System.Diagnostics.Stopwatch]::StartNew()
try {
  $r = Invoke-WebRequest -Uri 'https://registry.npmmirror.com/-/binary/git-for-windows/' -TimeoutSec 10 -ErrorAction Stop
  $sw.Stop(); Write-Output "npmmirror: OK $($sw.ElapsedMilliseconds)ms ($($r.Content.Length) bytes)"
} catch { $sw.Stop(); Write-Output "npmmirror 失败: $($_.Exception.Message) ($($sw.ElapsedMilliseconds)ms)" }
